#!/usr/bin/env node

import { existsSync, watch } from "node:fs";
import { resolve } from "node:path";
import { routerMapper } from "./mapper";
import { reactRouterWriter } from "./writers/react";

function parseArgs(args: string[]) {
    const options = {
        pages: "src/pages",
        output: "src/shared/router",
        name: "router",
        watch: false,
        help: false,
    };

    for (let i = 0; i < args.length; i++) {
        const arg = args[i];
        if (arg === "--help" || arg === "-h") {
            options.help = true;
        } else if (arg === "--watch" || arg === "-w") {
            options.watch = true;
        } else if ((arg === "--pages" || arg === "-p") && args[i + 1]) {
            options.pages = args[++i];
        } else if ((arg === "--out" || arg === "-o") && args[i + 1]) {
            options.output = args[++i];
        } else if ((arg === "--name" || arg === "-n") && args[i + 1]) {
            options.name = args[++i];
        }
    }

    return options;
}

function showHelp() {
    console.log(`
Usage: rakit-routes [options]

Automatic file-system based routing generator for React applications.

Options:
  -p, --pages <dir>     Directory containing page components (default: "src/pages")
  -o, --out <dir>       Directory for generated router file (default: "src/shared/router")
  -n, --name <filename> Output file name without extension (default: "router")
  -w, --watch           Watch pages directory and regenerate on changes
  -h, --help            Display this help message

Examples:
  npx @zarr20/rakit-routes
  npx @zarr20/rakit-routes --pages src/views --out src/routes
  npx @zarr20/rakit-routes --watch
`);
}

function generate(pagesDir: string, outputDir: string, fileName: string) {
    const startTime = performance.now();
    routerMapper({
        pages: { dir: pagesDir },
        output: { dir: outputDir, fileName },
        writer: reactRouterWriter()
    });
    const elapsed = (performance.now() - startTime).toFixed(1);
    console.log(`✨ Generated router in ${elapsed}ms`);
}

function main() {
    const options = parseArgs(process.argv.slice(2));

    if (options.help) {
        showHelp();
        process.exit(0);
    }

    const pagesResolved = resolve(process.cwd(), options.pages);

    if (!existsSync(pagesResolved)) {
        console.warn(`⚠️ Warning: Pages directory "${options.pages}" does not exist yet.`);
    }

    generate(options.pages, options.output, options.name);

    if (options.watch) {
        console.log(`👀 Watching for file changes in "${options.pages}"...`);
        let debounceTimer: NodeJS.Timeout | null = null;

        try {
            watch(pagesResolved, { recursive: true }, () => {
                if (debounceTimer) clearTimeout(debounceTimer);
                debounceTimer = setTimeout(() => {
                    console.log(`🔄 Detected changes in "${options.pages}", regenerating...`);
                    generate(options.pages, options.output, options.name);
                }, 100);
            });
        } catch (err: any) {
            console.error(`❌ Watch error: ${err.message}`);
        }
    }
}

main();
