import { relative } from "node:path";
import { scanPages } from "./core/scanner";
import { generateRouter } from "./core/generator";
import { RouterWriter } from "./writers/types";
import { reactRouterWriter } from "./writers/react";

export interface RouterMapperConfig {
    pages: {
        dir: string;
        extensions?: string[];
    };
    output: {
        dir: string;
        fileName?: string;
    };
    writer?: RouterWriter;
    importBase?: string;
}

/**
 * Computes a POSIX-compliant relative import path from one directory to another.
 */
export function computeRelativeImport(fromDir: string, toDir: string): string {
    let rel = relative(fromDir, toDir).replace(/\\/g, "/");
    if (!rel.startsWith(".")) {
        rel = "./" + rel;
    }
    return rel;
}

export function routerMapper(config: RouterMapperConfig): void {
    const files = scanPages(
        config.pages.dir,
        config.pages.extensions ?? [".tsx", ".ts", ".jsx", ".js"]
    );

    const routes = generateRouter(files);
    const writer = config.writer ?? reactRouterWriter();
    const importBase = config.importBase ?? computeRelativeImport(config.output.dir, config.pages.dir);

    writer.write(routes, {
        outputDir: config.output.dir,
        fileName: config.output.fileName ?? "router",
        importBase,
        pagesDir: config.pages.dir
    });
}
