import { existsSync, readdirSync } from "node:fs";
import { join } from "node:path";

/**
 * Recursively scans the pages directory for valid page components.
 * Automatically ignores hidden files, test files, and private folders (prefixed with _).
 */
export function scanPages(
    baseDir: string,
    extensions: string[] = [".tsx", ".ts", ".jsx", ".js"],
    dir = ""
): string[] {
    const target = join(baseDir, dir);
    if (!existsSync(target)) {
        return [];
    }

    const files: string[] = [];

    for (const entry of readdirSync(target, { withFileTypes: true })) {
        // Skip hidden files/directories (e.g. .DS_Store)
        if (entry.name.startsWith(".")) continue;

        if (entry.isDirectory()) {
            // Skip private folders starting with underscore (e.g. _components, _utils)
            if (entry.name.startsWith("_")) continue;
            files.push(...scanPages(baseDir, extensions, join(dir, entry.name)));
        } else {
            // Skip test and story files
            if (/\.(test|spec|stories)\.[^/.]+$/.test(entry.name)) continue;

            if (extensions.some(ext => entry.name.endsWith(ext))) {
                files.push(join(dir, entry.name));
            }
        }
    }

    return files;
}
